const Default = () => {
    const [open, setOpen] = useState(args.defaultOpen ?? false)

    return (
        <PageHeader
            brandName="Data Amsterdam"
            menuItems={[
              <PageHeader.MenuLink href="#" key={1} lang="en">
                English
              </PageHeader.MenuLink>,
              <PageHeader.MenuLink fixed href="#" icon={SearchIcon} key={2}>
                Zoeken
              </PageHeader.MenuLink>,
            ]}
            onClick={(event) => {
              // The links are placeholders; keep any Page Header link (logo, inline menu, mega menu) from
              // navigating, and close the mega menu the way an app would on navigation.
              if (event.target instanceof Element && event.target.closest('a')) {
                event.preventDefault()
                setOpen(false)
              }
            }}
            onOpenChange={(nextOpen) => {
              setOpen(nextOpen)
              args.onOpenChange?.(nextOpen)
            }}
            open={args.open ?? open}><Grid>
                <PageHeader.GridCellNarrowWindowOnly span="all">
                    <LinkList>
                        <LinkList.Link href="#" lang="en">English
