        <Grid.Cell span={{ narrow: 4, medium: 5, wide: 7 }}>
          <main className="ams-prose" id="inhoud">
            <Heading level={1}>{currentPage.heading}</Heading>
            <Paragraph size="large">{currentPage.lead}</Paragraph>
            <Paragraph>{currentPage.body}</Paragraph>
          </main>
        </Grid.Cell>
      </Grid>
    )
  },
}

