             * interrupting it, which keeps that label a contiguous part of the name for speech input.
             */}
            <Button variant="secondary">
              Toon op de kaart<span className="ams-visually-hidden">, {street}</span>
            </Button>
          </Grid.Cell>
        ))}
      </Grid.Subgrid>
    </Grid>
  </>)
);

